fn prime_num(n: u64) -> bool {
    // We assume n >= 2.
    // 2 and 3 are prime.
    if n <= 3 {
        return true;
    }
    // Even numbers greater than 2 are not prime.
    if n % 2 == 0 {
        return false;
    }
    // Only test odd divisors up to sqrt(n).
    // Use i <= n / i to avoid overflow in i * i.
    let mut i = 3;
    while i <= n / i {
        if n % i == 0 {
            return false;
        }
        i += 2;
    }
    true
}

